package android.app;import android.content.*; public class AlertDialog{public static android.widget.ScrollView view;public static DialogInterface.OnClickListener copy;public static class Builder{public Builder(Activity a){}public Builder setTitle(String s){return this;}public Builder setView(android.widget.ScrollView v){view=v;return this;}public Builder setPositiveButton(String s,DialogInterface.OnClickListener c){copy=c;return this;}public Builder setNeutralButton(String s,DialogInterface.OnClickListener c){return this;}public Builder setNegativeButton(String s,DialogInterface.OnClickListener c){return this;}public AlertDialog show(){return new AlertDialog();}}}